package br.com.minhalista.usuario;
import java.time.Instant; import java.util.Locale;
import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.HttpStatus; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import br.com.minhalista.assinatura.AssinaturaValidadeService; import br.com.minhalista.auth.PasswordChangeRateLimiter; import br.com.minhalista.common.RegraNegocioException;
@Service public class UsuarioService {
 private static final Logger LOGGER=LoggerFactory.getLogger(UsuarioService.class); private static final String EMAIL_FUNDADOR="smartlistevx@gmail.com"; private final UsuarioRepository repository; private final AssinaturaValidadeService assinaturaValidadeService; private final PasswordEncoder passwordEncoder; private final PasswordChangeRateLimiter passwordChangeRateLimiter;
 public UsuarioService(UsuarioRepository r,AssinaturaValidadeService a,PasswordEncoder p,PasswordChangeRateLimiter l){repository=r;assinaturaValidadeService=a;passwordEncoder=p;passwordChangeRateLimiter=l;}
 public Usuario obterAutenticado(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return repository.findByEmailIgnoreCase(email).orElseThrow(()->new RegraNegocioException(HttpStatus.UNAUTHORIZED,"Usuário autenticado não foi encontrado."));}
 public Usuario consultarPerfil(){Usuario u=obterAutenticado();try{assinaturaValidadeService.sincronizarUsuario(u);}catch(RuntimeException e){LOGGER.error("Falha ao sincronizar assinatura do usuário {}.",u.getId(),e);}return u;}
 @Transactional(readOnly=true) public CpfPerfilResponse consultarCpf(){return CpfPerfilResponse.de(obterAutenticado());}
 @Transactional public CpfPerfilResponse atualizarCpf(AtualizarCpfRequest request){Usuario u=obterAutenticado();if(!Cpf.valido(request.cpf()))throw new RegraNegocioException(HttpStatus.BAD_REQUEST,"Informe um CPF válido.");String cpf=Cpf.somenteDigitos(request.cpf());if(!cpf.equals(u.getCpf())&&repository.existsByCpf(cpf))throw new RegraNegocioException(HttpStatus.CONFLICT,"Este CPF já está cadastrado.");u.setCpf(cpf);try{repository.saveAndFlush(u);}catch(DataIntegrityViolationException e){throw new RegraNegocioException(HttpStatus.CONFLICT,"Este CPF já está cadastrado.");}return CpfPerfilResponse.de(u);}
 @Transactional public Usuario atualizarPerfil(AtualizarUsuarioRequest r){Usuario u=obterAutenticado();u.setNome(r.nome().trim());u.setTelefone(limparOpcional(r.telefone()));u.setCidade(limparOpcional(r.cidade()));u.setEstado(r.estado()==null||r.estado().isBlank()?null:r.estado().trim().toUpperCase(Locale.ROOT));u.setNotificarPromocoes(r.notificarPromocoes());u.setNotificarPrecos(r.notificarPrecos());return repository.save(u);}
 @Transactional public void alterarSenha(AlterarSenhaRequest r){Usuario u=obterAutenticado();passwordChangeRateLimiter.verificarPermitido(u.getId());if(!passwordEncoder.matches(r.senhaAtual(),u.getSenhaHash())){passwordChangeRateLimiter.registrarFalha(u.getId());throw new RegraNegocioException(HttpStatus.BAD_REQUEST,"Senha atual incorreta.");}if(r.senhaAtual().equals(r.novaSenha()))throw new RegraNegocioException(HttpStatus.BAD_REQUEST,"A nova senha deve ser diferente da senha atual.");u.setSenhaHash(passwordEncoder.encode(r.novaSenha()));repository.saveAndFlush(u);passwordChangeRateLimiter.limpar(u.getId());}
 @Transactional public Usuario atualizarFotoPerfil(String foto){if(foto==null||foto.isBlank()||!foto.startsWith("data:image/"))throw new RegraNegocioException(HttpStatus.BAD_REQUEST,"Foto de perfil inválida.");if(foto.length()>2_000_000)throw new RegraNegocioException(HttpStatus.PAYLOAD_TOO_LARGE,"A foto ficou muito grande. Escolha uma imagem menor.");Usuario u=obterAutenticado();u.setFotoPerfil(foto);return repository.save(u);}
 @Transactional public Usuario removerFotoPerfil(){Usuario u=obterAutenticado();u.setFotoPerfil(null);return repository.save(u);}
 @Transactional public void solicitarExclusaoEAnonimizacao(){Usuario u=obterAutenticado();if(EMAIL_FUNDADOR.equalsIgnoreCase(u.getEmail()))throw new RegraNegocioException(HttpStatus.FORBIDDEN,"A conta ADM principal não pode ser excluída.");String id=u.getId().toString();u.setNome("Conta excluída");u.setEmail("excluido-"+id+"@anonimo.smartlist");u.setCpf(null);u.setTelefone(null);u.setCidade(null);u.setEstado(null);u.setFotoPerfil(null);u.setSenhaHash("CONTA_EXCLUIDA_"+id);u.setPerfil(Perfil.USUARIO);u.setTipoAcesso(TipoAcesso.FREE);u.setCortesiaAte(null);u.setAtivo(false);u.setAceiteMarketing(false);u.setNotificarPromocoes(false);u.setNotificarPrecos(false);u.setExclusaoSolicitadaEm(Instant.now());repository.saveAndFlush(u);SecurityContextHolder.clearContext();}
 public void exigirPremium(Usuario u){assinaturaValidadeService.sincronizarUsuario(u);if(!u.temAcessoPremium())throw new RegraNegocioException(HttpStatus.FORBIDDEN,"Este recurso faz parte do plano Premium.");}
 private String limparOpcional(String v){return v==null||v.isBlank()?null:v.trim();}
}
